  "application": "report-generation",
  "case_id": "case-ipl-2026-ball-by-ball-analytics-en",
  "language": "en",
  "report": {
    "type": "analytics-report",
    "audience": "analyst",
    "tone": "analytical, detailed, data-forward"
  },
  "brief": {
    "title": "IPL 2026 Ball-by-Ball Analytics Report",
    "one_liner": "A comprehensive ball-by-ball analysis of the IPL 2026 season covering batting, bowling, extras, and dismissal patterns across all matches.",
    "goal": "Provide cricket analysts and team strategists with granular insights into scoring patterns, bowler effectiveness, dismissal trends, and team performance dynamics derived from delivery-level data to inform tactical decisions and fantasy cricket predictions."
  },
  "required_sections": [
    {
      "section_id": "tournament-overview",
      "title": "Tournament Overview & Match Summary",
      "objective": "Summarize the number of matches played, venues used, teams involved, total deliveries bowled, and overall run-scoring and wicket-taking aggregates across the tournament."
    },
    {
      "section_id": "batting-analysis",
      "title": "Batting Performance Analysis",
      "objective": "Identify top run-scorers by aggregating runs_of_bat per striker, analyze boundary frequency (4s and 6s), strike rates, and scoring patterns across overs (powerplay, middle overs, death overs)."
    },
    {
      "section_id": "bowling-analysis",
      "title": "Bowling Performance Analysis",
      "objective": "Rank bowlers by wickets taken, economy rate, and dot-ball percentage. Analyze dismissal types and identify the most effective bowlers in different match phases."
    },
    {
      "section_id": "team-comparison",
      "title": "Team Performance Comparison",
      "objective": "Compare batting and bowling team performances including average runs per innings, extras conceded, wickets lost, and net scoring rates to highlight the strongest and weakest teams."
    },
    {
      "section_id": "extras-discipline",
      "title": "Extras & Bowling Discipline",
      "objective": "Analyze the distribution of extras (wides, no-balls, byes, leg-byes) by team and bowler to assess bowling discipline and its impact on match outcomes."
    },
    {
      "section_id": "venue-insights",
      "title": "Venue & Match Phase Insights",
      "objective": "Examine scoring trends by venue and by match phase (innings, over ranges) to identify high-scoring grounds and the impact of batting first vs. chasing."
    }
  ],
  "kpis": [
    {
      "name": "Average Runs Per Over",
      "description": "Total runs scored (runs_of_bat + extras) divided by total overs bowled, indicating the overall scoring rate of the tournament."
    },
    {
      "name": "Boundary Percentage",
      "description": "Percentage of deliveries that resulted in a four (runs_of_bat=4) or six (runs_of_bat=6) out of all deliveries faced."
    },
    {
      "name": "Dot Ball Percentage",
      "description": "Percentage of deliveries where runs_of_bat=0 and extras=0, reflecting bowling pressure across the tournament."
    },
    {
      "name": "Extras Per Match",
      "description": "Average total extras (wides, no-balls, byes, leg-byes) conceded per match, indicating overall bowling discipline."
    },
    {
      "name": "Wickets Per Match",
      "description": "Average number of wickets falling per match, reflecting the balance between bat and ball."
    }
  ],
  "analysis_dimensions": [
    "batting_team",
    "bowling_team",
    "over",
    "venue",
    "bowler"
  ]
}

